# Rosdahl - Textbook of Basic Nursing (Wolters Kluwer).
# Chapter list: 12th edition, from the publisher's table of contents (shop.lww.com). A 13th edition is
# forthcoming; chapters may shift. Summaries are written for this site, not copied from the book.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "The Origins of Nursing", "Modern nursing began with Florence Nightingale, who improved sanitation during the Crimean War and founded nursing education. Other pioneers include Clara Barton (American Red Cross), Mary Mahoney (first African American professional nurse), and Lillian Wald (public health nursing).", ["Florence Nightingale", "Clara Barton: Red Cross", "Mary Mahoney", "Lillian Wald: public health"]),
    ch(2, "Beginning Your Nursing Career", "Practical/vocational nurses (LPN/LVN) complete a state-approved program and pass the NCLEX-PN. They work under the direction of an RN or physician. Success requires study skills, time management, and professionalism.", ["NCLEX-PN", "Work under RN direction", "Study skills", "Professionalism"]),
    ch(3, "The Healthcare Delivery System", "Health care is delivered in hospitals, long-term care, clinics, home health, and hospice. Payment comes from Medicare, Medicaid, private insurance, and managed care. The health care team works together, and quality is measured by accreditation such as The Joint Commission.", ["Care settings", "Medicare and Medicaid", "Managed care", "Joint Commission"]),
    ch(4, "Legal and Ethical Aspects of Nursing", "Nurse practice acts define scope of practice. Legal issues include negligence, malpractice, informed consent, confidentiality (HIPAA), and documentation. Ethical principles include autonomy, beneficence, nonmaleficence, justice, and fidelity. Advance directives guide end-of-life care.", ["Nurse practice act", "Negligence and malpractice", "HIPAA", "Ethical principles"]),
    ch(5, "Basic Human Needs", "Maslow's hierarchy ranks needs from physiological (air, water, food) to safety, love and belonging, esteem, and self-actualization. Nurses prioritize physiological needs first.", ["Maslow's hierarchy", "Physiological needs first", "Safety", "Self-actualization"]),
    ch(6, "Health and Wellness", "Health is complete physical, mental, and social well-being (WHO). Wellness is a lifelong process influenced by lifestyle. Levels of prevention: primary (prevent disease), secondary (early detection), tertiary (limit disability).", ["WHO definition", "Wellness continuum", "Levels of prevention", "Lifestyle"]),
    ch(7, "Community Health", "Community health focuses on populations: immunizations, sanitation, disease surveillance, health education, and disaster preparedness. Public health agencies include the CDC and local health departments.", ["Population focus", "Immunizations", "Disease surveillance", "Health departments"]),
    ch(8, "Transcultural Healthcare", "Culture shapes health beliefs, diet, communication, family roles, and religious practices. Culturally competent nurses avoid stereotyping and ethnocentrism, use interpreters, and respect beliefs.", ["Cultural competence", "Avoid ethnocentrism", "Use interpreters", "Respect beliefs"]),
    ch(9, "The Family", "Family structures include nuclear, extended, single-parent, and blended. Families provide support, socialization, and care. Stressors like illness affect the whole family.", ["Family structures", "Family functions", "Illness affects family", "Support systems"]),
    ch(10, "Infancy and Childhood", "Growth and development follow predictable patterns. Infants triple birth weight by 1 year. Theories include Erikson (trust vs. mistrust, autonomy, initiative, industry) and Piaget. Immunizations and safety are priorities.", ["Triple birth weight by 1 year", "Erikson's stages", "Milestones", "Immunizations"]),
    ch(11, "Adolescence", "Adolescence brings puberty and identity formation (Erikson: identity vs. role confusion). Risks include accidents, substance use, eating disorders, and depression. Confidentiality and respect build trust.", ["Puberty", "Identity vs. role confusion", "Risk behaviors", "Confidentiality"]),
    ch(12, "Early and Middle Adulthood", "Early adults focus on intimacy, careers, and families (intimacy vs. isolation). Middle adults face physical changes and generativity vs. stagnation. Screening for chronic diseases becomes important.", ["Intimacy vs. isolation", "Generativity vs. stagnation", "Screening", "Career and family"]),
    ch(13, "Older Adulthood and Aging", "Aging brings changes in skin, bones, senses, and organ function, but disease and confusion aren't normal aging. Erikson's stage is integrity vs. despair. Promote independence and safety, especially fall prevention.", ["Integrity vs. despair", "Normal aging changes", "Fall prevention", "Independence"]),
    ch(14, "The End of Life: Death, Dying, Grief, and Loss", "Kübler-Ross described stages of grief: denial, anger, bargaining, depression, acceptance. Signs of approaching death include mottled skin, Cheyne-Stokes breathing, and decreased urine. Hearing is thought to be the last sense lost.", ["Stages of grief", "Signs of approaching death", "Hearing last sense", "Support families"]),
    ch(15, "Organization of the Human Body", "The body is organized from cells to tissues, organs, and systems. Anatomical position, planes, directional terms, and body cavities describe location. Homeostasis maintains balance.", ["Levels of organization", "Directional terms", "Body cavities", "Homeostasis"]),
    ch(16, "The Integumentary System", "Skin has the epidermis, dermis, and subcutaneous layer. It protects, regulates temperature, senses, and makes vitamin D. Accessory structures include hair, nails, and glands.", ["Epidermis and dermis", "Protection", "Temperature regulation", "Vitamin D"]),
    ch(17, "Fluid and Electrolyte Balance", "Body fluids are intracellular and extracellular. Key electrolytes: sodium (135–145 mEq/L), potassium (3.5–5.0 mEq/L), calcium, and chloride. Fluid moves by osmosis, diffusion, and filtration. Acid-base balance keeps pH 7.35–7.45.", ["Na+ 135–145", "K+ 3.5–5.0", "Osmosis", "pH 7.35–7.45"]),
    ch(18, "The Musculoskeletal System", "The skeleton (206 bones) supports and protects; muscles move the body. Joints include synovial joints. Bones store calcium and make blood cells.", ["206 bones", "Muscle types", "Synovial joints", "Blood cell production"]),
    ch(19, "The Nervous System", "The CNS (brain and spinal cord) and PNS (cranial and spinal nerves, autonomic system) control the body. The cerebrum handles thought, the cerebellum balance, the brainstem vital functions.", ["CNS and PNS", "Cerebrum, cerebellum, brainstem", "Autonomic system", "Neurons"]),
    ch(20, "The Endocrine System", "Glands release hormones: pituitary (master gland), thyroid (metabolism), parathyroid (calcium), adrenals (cortisol, epinephrine), pancreas (insulin, glucagon), and gonads.", ["Pituitary master gland", "Thyroid: metabolism", "Insulin and glucagon", "Adrenal hormones"]),
    ch(21, "The Sensory System", "The senses include vision (eye: cornea, lens, retina), hearing and balance (ear), taste, smell, and touch. Sensory changes affect safety and communication.", ["Eye structures", "Ear: hearing and balance", "Taste and smell", "Safety"]),
    ch(22, "The Cardiovascular System", "The heart has four chambers and valves; blood flows through pulmonary and systemic circulation. The SA node is the pacemaker. Arteries, veins, and capillaries carry blood.", ["Four chambers", "SA node", "Pulmonary vs. systemic", "Vessel types"]),
    ch(23, "The Hematologic and Lymphatic Systems", "Blood contains plasma, RBCs (oxygen), WBCs (infection), and platelets (clotting). The lymphatic system returns fluid and supports immunity through lymph nodes, spleen, and thymus.", ["Blood components", "Platelets clot", "Lymph nodes", "Spleen"]),
    ch(24, "The Immune System", "Immunity protects against pathogens. Innate immunity is nonspecific; acquired immunity uses B cells (antibodies) and T cells. Immunity can be active or passive.", ["Innate vs. acquired", "B and T cells", "Active vs. passive", "Antibodies"]),
    ch(25, "The Respiratory System", "Air flows through the nose, pharynx, larynx, trachea, bronchi, and alveoli, where gas exchange occurs. The diaphragm is the main breathing muscle.", ["Pathway of air", "Alveoli exchange gases", "Diaphragm", "Respiration control"]),
    ch(26, "The Digestive System", "Digestion runs from mouth to anus. The small intestine absorbs most nutrients; the liver makes bile; the pancreas makes enzymes and insulin; the large intestine absorbs water.", ["Small intestine absorbs", "Liver makes bile", "Pancreas enzymes", "Large intestine absorbs water"]),
    ch(27, "The Urinary System", "The kidneys filter blood through nephrons, producing urine that passes through the ureters, bladder, and urethra. Kidneys regulate fluids, electrolytes, and blood pressure.", ["Nephrons", "Urine pathway", "Fluid balance", "Blood pressure regulation"]),
    ch(28, "The Male Reproductive System", "The testes produce sperm and testosterone. Other structures include the epididymis, vas deferens, prostate, seminal vesicles, and penis.", ["Testes: sperm and testosterone", "Prostate", "Vas deferens", "Epididymis"]),
    ch(29, "The Female Reproductive System", "The ovaries produce eggs, estrogen, and progesterone. Fertilization occurs in the fallopian tubes; the uterus supports pregnancy. The menstrual cycle averages 28 days.", ["Ovaries", "Fallopian tubes: fertilization", "Uterus", "28-day cycle"]),
    ch(30, "Basic Nutrition", "Nutrients are carbohydrates, proteins, fats, vitamins, minerals, and water. MyPlate guides healthy eating. Calories: carbs and protein 4/g, fat 9/g.", ["Six nutrients", "MyPlate", "Calories per gram", "Water is essential"]),
    ch(31, "Transcultural and Social Aspects of Nutrition", "Food choices reflect culture, religion (e.g., kosher, halal, vegetarian traditions), income, and social factors. Nurses respect dietary preferences and restrictions.", ["Cultural food practices", "Religious restrictions", "Income and access", "Respect preferences"]),
    ch(32, "Diet Therapy and Special Diets", "Therapeutic diets include clear liquid, full liquid, soft, mechanical soft, low-sodium, diabetic (carbohydrate-controlled), renal, and modified consistency for dysphagia. Enteral (tube) and parenteral (IV) nutrition support patients who can't eat.", ["Clear vs. full liquid", "Low-sodium diets", "Dysphagia diets", "Enteral vs. parenteral"]),
    ch(33, "Introduction to the Nursing Process", "The nursing process is assessment, diagnosis, planning, implementation, and evaluation (ADPIE). It's a systematic, patient-centered way to plan care.", ["ADPIE", "Systematic", "Patient-centered", "Continuous"]),
    ch(34, "Nursing Assessment", "Assessment collects subjective (what the patient says) and objective (what the nurse observes or measures) data through interview, observation, and physical exam.", ["Subjective vs. objective", "Interview", "Physical exam", "Data collection"]),
    ch(35, "Nursing Diagnosis and Planning", "Nursing diagnoses describe patient responses to health problems. Planning sets priorities and measurable, patient-centered goals (SMART) with interventions.", ["Nursing diagnosis", "Prioritize", "Measurable goals", "Care plan"]),
    ch(36, "Implementing and Evaluating Care", "Implementation carries out interventions; evaluation measures whether goals were met and revises the plan if needed.", ["Carry out interventions", "Evaluate goals", "Revise plan", "Delegate appropriately"]),
    ch(37, "Documenting and Reporting", "Documentation is a legal record and must be accurate, timely, and objective. Formats include narrative, SOAP, and charting by exception. Handoff reports often use SBAR.", ["Legal record", "SOAP", "SBAR handoffs", "Objective and timely"]),
    ch(38, "The Healthcare Facility Environment", "A safe environment includes fall prevention, call lights within reach, bed in low position, fire safety (RACE, PASS), restraint alternatives, and electrical and chemical safety.", ["Fall prevention", "RACE and PASS", "Restraint alternatives", "Call light in reach"]),
    ch(39, "Emergency Preparedness", "Facilities plan for internal and external disasters, bioterrorism, and mass casualties. Triage sorts victims by priority. Nurses know their roles in the emergency plan.", ["Disaster plans", "Triage", "Bioterrorism", "Know your role"]),
    ch(40, "Introduction to Microbiology", "Microorganisms include bacteria, viruses, fungi, protozoa, and helminths. Pathogens cause disease; normal flora usually don't. Spores are most resistant.", ["Types of microorganisms", "Pathogens vs. normal flora", "Spores", "Conditions for growth"]),
    ch(41, "Medical Asepsis", "Medical asepsis (clean technique) reduces microorganisms through hand hygiene, cleaning, and disinfection. Hand hygiene is the most important infection control measure.", ["Clean technique", "Hand hygiene", "Disinfection", "Chain of infection"]),
    ch(42, "Infection Control", "Standard precautions apply to all patients. Transmission-based precautions are contact (gown, gloves), droplet (mask), and airborne (N95, negative-pressure room). Healthcare-associated infections are prevented with these measures.", ["Standard precautions", "Contact, droplet, airborne", "N95 for airborne", "HAIs"]),
    ch(43, "Emergency Care and First Aid", "First aid includes CPR and AED, choking relief, bleeding control, shock, burns, fractures, poisoning, and heat and cold emergencies. Check scene safety first.", ["CPR and AED", "Choking", "Bleeding control", "Scene safety"]),
    ch(44, "Therapeutic Communication Skills", "Therapeutic communication uses active listening, open-ended questions, reflection, clarification, and silence. Barriers include false reassurance, giving advice, and changing the subject.", ["Open-ended questions", "Active listening", "Avoid false reassurance", "Reflection"]),
    ch(45, "Admission, Transfer, and Discharge", "Admission orients the patient and gathers baseline data and belongings; transfer moves care safely with a report; discharge includes teaching, medication reconciliation, and follow-up plans.", ["Orientation", "Baseline data", "Handoff report", "Discharge teaching"]),
    ch(46, "Vital Signs", "Vital signs: temperature (oral ~98.6°F/37°C), pulse (60–100), respirations (12–20), blood pressure (<120/80), oxygen saturation (95–100%), and pain. Rectal temperatures run higher; axillary lower.", ["Pulse 60–100", "Respirations 12–20", "BP < 120/80", "SpO2 95–100%"]),
    ch(47, "Data Collection in Client Care", "Data collection includes height and weight, head-to-toe assessment, inspection, palpation, percussion, and auscultation, and assisting with exams.", ["Inspection, palpation, percussion, auscultation", "Head-to-toe", "Height and weight", "Assist with exams"]),
    ch(48, "Moving and Positioning Clients", "Use body mechanics and lift equipment. Positions include supine, prone, Fowler's (sitting up), Sims' (left side-lying), lateral, and Trendelenburg. Reposition at least every 2 hours.", ["Body mechanics", "Fowler's and Sims'", "Reposition every 2 hours", "Lift equipment"]),
    ch(49, "Beds and Bed Making", "Bed making includes unoccupied, occupied, and surgical beds. Keep linens wrinkle-free, don't shake linens, and hold them away from your uniform.", ["Occupied bed", "Don't shake linens", "Wrinkle-free", "Surgical bed"]),
    ch(50, "Personal Hygiene", "Hygiene care includes bathing, oral care, perineal care (front to back), hair, nail, and foot care (careful with diabetics), and dressing (weak side first).", ["Perineal care front to back", "Oral care", "Diabetic foot care", "Dress weak side first"]),
    ch(51, "Elimination", "Elimination care includes bedpans and urinals, catheter care (bag below bladder), enemas (left Sims' position), ostomy care, and monitoring intake and output.", ["Catheter bag below bladder", "Enema: left Sims'", "Ostomy care", "Intake and output"]),
    ch(52, "Specimen Collection", "Specimens include clean-catch urine, 24-hour urine (discard first void), stool (including occult blood), sputum (early morning), and cultures. Label specimens accurately and transport promptly.", ["Clean-catch urine", "24-hour urine: discard first", "Sputum in the morning", "Label correctly"]),
]

